"""
Backport Generator - Generate implementation code for backported features
=========================================================================

This module generates:
1. Eluna Lua scripts for custom spell logic
2. SQL entries for spell_dbc, creature_template, etc.
3. DBC modification instructions
4. Complete backport packages

Uses Cardinal (Mistral) for intelligent code generation based on
learned patterns from successful backports.
"""

import json
import asyncio
from dataclasses import dataclass, field, asdict
from typing import Optional, Dict, Any, List
from pathlib import Path
from datetime import datetime
import httpx

from .spell_analyzer import SpellData, SpellEffect, VersionComparison
from .knowledge_manager import KnowledgeManager, BackportPattern


# =============================================================================
# RESULT STRUCTURES
# =============================================================================

@dataclass
class GeneratedCode:
    """A single generated code file"""
    filename: str
    language: str  # "lua", "sql", "text"
    content: str
    description: str = ""
    dependencies: List[str] = field(default_factory=list)


@dataclass
class BackportResult:
    """Complete backport generation result"""
    spell_id: int
    spell_name: str
    status: str  # "success", "partial", "failed"
    timestamp: str = ""

    # Generated files
    eluna_scripts: List[GeneratedCode] = field(default_factory=list)
    sql_entries: List[GeneratedCode] = field(default_factory=list)
    dbc_instructions: List[str] = field(default_factory=list)

    # Metadata
    patterns_used: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    notes: str = ""

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["eluna_scripts"] = [asdict(s) for s in self.eluna_scripts]
        d["sql_entries"] = [asdict(s) for s in self.sql_entries]
        return d


