# =============================================================================
# BACKPORT GENERATOR
# =============================================================================

class BackportGenerator:
    """
    Main code generation engine for backports.

    Uses Cardinal (Mistral) for intelligent code generation,
    informed by patterns learned from previous successful backports.
    """

    def __init__(
        self,
        knowledge_manager: Optional[KnowledgeManager] = None,
        ollama_url: str = "http://localhost:11434",
        ollama_model: str = "mistral",
        output_path: Optional[Path] = None,
    ):
        """
        Initialize the backport generator.

        Args:
            knowledge_manager: KnowledgeManager for pattern lookup
            ollama_url: Ollama server URL
            ollama_model: Model to use for generation
            output_path: Where to save generated files
        """
        self.km = knowledge_manager or KnowledgeManager()
        self.ollama_url = ollama_url
        self.ollama_model = ollama_model
        self.output_path = Path(output_path) if output_path else Path("C:/Akashic_Cardinal_Sandbox/backports")
        self.output_path.mkdir(parents=True, exist_ok=True)

    # =========================================================================
    # MAIN GENERATION
    # =========================================================================

    async def generate_backport(
        self,
        comparison: VersionComparison,
        options: Optional[Dict[str, Any]] = None,
    ) -> BackportResult:
        """
        Generate a complete backport package for a spell.

        Args:
            comparison: Version comparison result from SpellAnalyzer
            options: Generation options (custom_id, include_npc, etc.)

        Returns:
            BackportResult with all generated code
        """
        options = options or {}
        timestamp = datetime.now().isoformat()

        result = BackportResult(
            spell_id=comparison.spell_id,
            spell_name=comparison.spell_name,
            status="pending",
            timestamp=timestamp,
        )

        if not comparison.can_backport and comparison.backport_difficulty == "impossible":
            result.status = "failed"
            result.notes = "Spell cannot be backported due to engine limitations."
            result.warnings = comparison.engine_limitations
            return result

        # Get relevant patterns
        patterns = []
        if comparison.retail_data:
            for effect in comparison.retail_data.effects:
                pattern = self.km.get_pattern_for_mechanic(effect.effect_type_name.lower())
                if pattern:
                    patterns.append(pattern)
                    result.patterns_used.append(pattern.id)

        # Generate Eluna scripts
        eluna_scripts = await self._generate_eluna(comparison, patterns, options)
        result.eluna_scripts = eluna_scripts

        # Generate SQL
        sql_entries = await self._generate_sql(comparison, options)
        result.sql_entries = sql_entries

        # Generate DBC instructions
        dbc_instructions = self._generate_dbc_instructions(comparison)
        result.dbc_instructions = dbc_instructions

        # Determine status
        if eluna_scripts or sql_entries:
            result.status = "success" if not result.warnings else "partial"
        else:
            result.status = "failed"
            result.notes = "Failed to generate any implementation code."

        # Save result
        await self._save_result(result)

        return result

    # =========================================================================
    # ELUNA GENERATION
    # =========================================================================

    async def _generate_eluna(
        self,
        comparison: VersionComparison,
        patterns: List[BackportPattern],
        options: Dict[str, Any],
    ) -> List[GeneratedCode]:
        """Generate Eluna Lua scripts."""
        scripts = []
        retail = comparison.retail_data
        if not retail:
            return scripts

        # Build prompt for Cardinal
        pattern_examples = "\n\n".join([
            f"Pattern: {p.name}\n```lua\n{p.code_template[:500]}\n```"
            for p in patterns[:3]
        ]) if patterns else "No existing patterns found."

        prompt = f"""Generate an Eluna Lua script to backport this spell to AzerothCore 3.3.5a:

## SPELL DATA
- ID: {retail.id}
- Name: {retail.name}
- Description: {retail.description[:500] if retail.description else 'N/A'}
- Effects: {json.dumps([e.to_dict() for e in retail.effects], indent=2)}
- School: {retail.school_name}
- Cast Time: {retail.cast_time}ms
- Mana Cost: {retail.mana_cost}
- Duration: {retail.duration_ms}ms

## EXISTING PATTERNS
{pattern_examples}

## REQUIREMENTS
1. Use proper Eluna API functions
2. Handle edge cases (no target, dead target, etc.)
3. Include comments explaining the logic
4. Use PLAYER_EVENT_ON_SPELL_CAST (event 5) for spell handlers
5. Use appropriate target validation

## ELUNA API REFERENCE (3.3.5a)
- player:GetTarget() - Get player's current target
- player:CastSpell(target, spellId) - Cast spell
- target:GetHealth() / target:GetMaxHealth() - Health
- target:ModifyHealth(amount) - Modify health
- target:AddAura(spellId, player) - Add aura
- target:HasAura(spellId) - Check aura
- target:RemoveAura(spellId) - Remove aura
- target:DealDamage(target, amount, spellId) - Deal damage
- RegisterPlayerEvent(eventId, function) - Register handler

Generate ONLY the Lua code, no explanations outside of code comments."""

        try:
            async with httpx.AsyncClient(timeout=120) as client:
                response = await client.post(
                    f"{self.ollama_url}/api/generate",
                    json={
                        "model": self.ollama_model,
                        "prompt": prompt,
                        "system": "You are Cardinal, generating Eluna Lua scripts for AzerothCore 3.3.5a. Write clean, well-commented code.",
                        "stream": False,
                        "options": {"temperature": 0.4},
                    }
                )

                if response.status_code == 200:
                    code = response.json().get("response", "")

                    # Clean up code (remove markdown if present)
                    if "```lua" in code:
                        code = code.split("```lua")[1].split("```")[0]
                    elif "```" in code:
                        code = code.split("```")[1].split("```")[0]

                    scripts.append(GeneratedCode(
                        filename=f"spell_{retail.id}_{retail.name.lower().replace(' ', '_')}.lua",
                        language="lua",
                        content=code.strip(),
                        description=f"Main spell handler for {retail.name}",
                    ))

        except Exception as e:
            # Fallback: use template
            scripts.append(self._generate_template_eluna(retail))

        return scripts

    def _generate_template_eluna(self, spell: SpellData) -> GeneratedCode:
        """Generate Eluna script from template."""
        # Determine spell logic based on effects
        spell_logic = "-- TODO: Implement spell logic\n"
        for effect in spell.effects:
            if "DAMAGE" in effect.effect_type_name.upper():
                spell_logic += f"    target:DealDamage(target, {effect.base_points}, SPELL_ID)\n"
            elif "HEAL" in effect.effect_type_name.upper():
                spell_logic += f"    target:ModifyHealth({effect.base_points})\n"
            elif "AURA" in effect.effect_type_name.upper():
                spell_logic += f"    target:AddAura(SPELL_ID, player)\n"

        content = ELUNA_SPELL_TEMPLATE.format(
            spell_id=spell.id,
            spell_name=spell.name,
            timestamp=datetime.now().isoformat(),
            description=spell.description[:200] if spell.description else "N/A",
            notes="Generated from template",
            custom_variables="",
            spell_logic=spell_logic,
            additional_handlers="",
        )

        return GeneratedCode(
            filename=f"spell_{spell.id}_{spell.name.lower().replace(' ', '_')}.lua",
            language="lua",
            content=content,
            description=f"Template-based handler for {spell.name}",
        )

    # =========================================================================
    # SQL GENERATION
    # =========================================================================

    async def _generate_sql(
        self,
        comparison: VersionComparison,
        options: Dict[str, Any],
    ) -> List[GeneratedCode]:
        """Generate SQL database entries."""
        sql_files = []
        retail = comparison.retail_data
        wotlk = comparison.wotlk_data

        if not retail:
            return sql_files

        # If spell exists in 3.3.5a, we might just need minor modifications
        if wotlk:
            # Generate modification SQL
            sql_files.append(self._generate_modification_sql(retail, wotlk))
        else:
            # Generate new spell entry
            sql_files.append(self._generate_new_spell_sql(retail, options))

        # Optional: Generate trainer NPC
        if options.get("include_npc", False):
            sql_files.append(self._generate_trainer_sql(retail, options))

        return sql_files

    def _generate_new_spell_sql(
        self,
        spell: SpellData,
        options: Dict[str, Any],
    ) -> GeneratedCode:
        """Generate SQL for a completely new spell."""
        # Use custom ID if provided (to avoid conflicts)
        spell_id = options.get("custom_spell_id", spell.id + 900000)

        # Extract effect data
        effects = spell.effects + [SpellEffect(index=i, effect_type=0) for i in range(len(spell.effects), 3)]

        content = SQL_SPELL_DBC_TEMPLATE.format(
            spell_id=spell_id,
            spell_name=spell.name[:64],  # Max length
            timestamp=datetime.now().isoformat(),
            dispel=spell.dispel_type,
            mechanic=spell.mechanic,
            attributes=spell.attributes[0] if spell.attributes else 0,
            cast_time_index=1,  # Index into SpellCastTimes.dbc
            recovery_time=spell.recovery_time,
            base_level=1,
            spell_level=80,
            duration_index=1,  # Index into SpellDuration.dbc
            power_type=spell.power_type,
            mana_cost=spell.mana_cost,
            range_index=1,  # Index into SpellRange.dbc
            effect1=effects[0].effect_type,
            effect2=effects[1].effect_type,
            effect3=effects[2].effect_type,
            base_points1=effects[0].base_points,
            base_points2=effects[1].base_points,
            base_points3=effects[2].base_points,
            target_a1=effects[0].implicit_target_a,
            target_a2=effects[1].implicit_target_a,
            target_a3=effects[2].implicit_target_a,
            aura1=effects[0].aura_type,
            aura2=effects[1].aura_type,
            aura3=effects[2].aura_type,
            misc1=effects[0].misc_value,
            misc2=effects[1].misc_value,
            misc3=effects[2].misc_value,
            trigger1=effects[0].trigger_spell,
            trigger2=effects[1].trigger_spell,
            trigger3=effects[2].trigger_spell,
            icon_id=1,  # SpellIcon.dbc reference
            description=(spell.description[:255] if spell.description else "").replace("'", "''"),
            tooltip=(spell.tooltip[:255] if spell.tooltip else "").replace("'", "''"),
            spell_family=0,
            dmg_class=1,  # 0=none, 1=magic, 2=melee, 3=ranged
            school_mask=spell.school,
            additional_sql="",
        )

        return GeneratedCode(
            filename=f"spell_{spell_id}_{spell.name.lower().replace(' ', '_')}.sql",
            language="sql",
            content=content,
            description=f"New spell entry for {spell.name}",
        )

    def _generate_modification_sql(
        self,
        retail: SpellData,
        wotlk: SpellData,
    ) -> GeneratedCode:
        """Generate SQL to modify an existing spell."""
        content = f"""-- {retail.name} Modification SQL
-- Modifies existing 3.3.5a spell to match retail behavior
-- Generated by Cardinal WoW Backport System
-- Date: {datetime.now().isoformat()}

-- Original 3.3.5a spell ID: {wotlk.id}
-- Retail reference ID: {retail.id}

-- Backup original values (comment out after first run)
-- SELECT * FROM spell_dbc WHERE Id = {wotlk.id};

-- Modify base points if needed
-- UPDATE spell_dbc SET EffectBasePoints1 = {retail.effects[0].base_points if retail.effects else 0} WHERE Id = {wotlk.id};

-- Note: Most spell modifications in 3.3.5a are done via Eluna scripts
-- rather than modifying spell_dbc directly, as it provides more flexibility.

-- See the accompanying Lua script for runtime modifications.
"""

        return GeneratedCode(
            filename=f"spell_{wotlk.id}_modify.sql",
            language="sql",
            content=content,
            description=f"Modifications for existing spell {wotlk.name}",
        )

    def _generate_trainer_sql(
        self,
        spell: SpellData,
        options: Dict[str, Any],
    ) -> GeneratedCode:
        """Generate SQL for a trainer NPC."""
        npc_id = options.get("npc_id", 900000 + spell.id)
        npc_name = options.get("npc_name", f"{spell.name} Trainer")

        content = SQL_CREATURE_TEMPLATE.format(
            npc_id=npc_id,
            npc_name=npc_name,
        )

        return GeneratedCode(
            filename=f"npc_{npc_id}_{spell.name.lower().replace(' ', '_')}_trainer.sql",
            language="sql",
            content=content,
            description=f"Trainer NPC for {spell.name}",
        )

    # =========================================================================
    # DBC INSTRUCTIONS
    # =========================================================================

    def _generate_dbc_instructions(self, comparison: VersionComparison) -> List[str]:
        """Generate DBC modification instructions."""
        instructions = []

        if comparison.wotlk_data:
            instructions.append(
                f"Spell {comparison.spell_id} exists in 3.3.5a. "
                "DBC modification may not be necessary."
            )
        else:
            instructions.append(
                f"Spell {comparison.spell_id} does not exist in 3.3.5a. "
                "Options:"
            )
            instructions.append("1. Use the provided SQL to add to spell_dbc (recommended)")
            instructions.append("2. Modify Spell.dbc directly using a DBC editor:")
            instructions.append("   - Open Spell.dbc with MyDBCEditor or WDBX")
            instructions.append("   - Add new row with appropriate values")
            instructions.append("   - Export and place in data/dbc folder")
            instructions.append("3. Use Eluna SPELL_EVENT hooks for custom behavior")

        return instructions

    # =========================================================================
    # OUTPUT
    # =========================================================================

    async def _save_result(self, result: BackportResult):
        """Save generated result to disk."""
        # Create spell directory
        spell_dir = self.output_path / f"spell_{result.spell_id}_{result.spell_name.lower().replace(' ', '_')}"
        spell_dir.mkdir(parents=True, exist_ok=True)

        # Save Eluna scripts
        lua_dir = spell_dir / "lua"
        lua_dir.mkdir(exist_ok=True)
        for script in result.eluna_scripts:
            (lua_dir / script.filename).write_text(script.content)

        # Save SQL
        sql_dir = spell_dir / "sql"
        sql_dir.mkdir(exist_ok=True)
        for sql in result.sql_entries:
            (sql_dir / sql.filename).write_text(sql.content)

        # Save instructions
        if result.dbc_instructions:
            (spell_dir / "DBC_INSTRUCTIONS.txt").write_text("\n".join(result.dbc_instructions))

        # Save manifest
        manifest = result.to_dict()
        (spell_dir / "manifest.json").write_text(json.dumps(manifest, indent=2))

    # =========================================================================
    # BATCH GENERATION
    # =========================================================================

    async def batch_generate(
        self,
        comparisons: List[VersionComparison],
        options: Optional[Dict[str, Any]] = None,
    ) -> List[BackportResult]:
        """Generate backports for multiple spells."""
        results = []
        for comparison in comparisons:
            result = await self.generate_backport(comparison, options)
            results.append(result)
            await asyncio.sleep(1)  # Rate limiting
        return results


